-- Accounts cell (accounts), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA accounts;

CREATE FUNCTION accounts.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE accounts.identities (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    slug                     text NOT NULL CHECK (length(slug) <= 120 AND length(slug) >= 1),
    display_name             text NOT NULL CHECK (length(display_name) <= 200 AND length(display_name) >= 1),
    trust_zone               text NOT NULL CHECK (trust_zone IN ('z0-root', 'z1-public', 'z2-business', 'z2-separated')),
    isolation_group          text CHECK (isolation_group IS NULL OR (length(isolation_group) <= 120)),
    relation                 text NOT NULL DEFAULT 'self' CHECK (relation IN ('self', 'family', 'work', 'client')),
    status                   text NOT NULL DEFAULT 'active' CHECK (status IN ('planned', 'active', 'paused', 'retired')),
    notes                    text CHECK (notes IS NULL OR (length(notes) <= 4000)),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, slug)
);
CREATE UNIQUE INDEX identities_legacy ON accounts.identities (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX identities_isolation_group ON accounts.identities (workspace_id, isolation_group);
CREATE INDEX identities_relation ON accounts.identities (workspace_id, relation);
CREATE INDEX identities_status ON accounts.identities (workspace_id, status);
CREATE INDEX identities_trust_zone ON accounts.identities (workspace_id, trust_zone);

CREATE TABLE accounts.domains (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 253 AND length(name) >= 1),
    identity_id              bigint,
    registrar                text CHECK (registrar IS NULL OR (length(registrar) <= 120)),
    dns_provider             text CHECK (dns_provider IS NULL OR (length(dns_provider) <= 120)),
    mail_provider            text CHECK (mail_provider IS NULL OR (length(mail_provider) <= 120)),
    auto_renew               boolean NOT NULL DEFAULT true,
    renews_on                date,
    status                   text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'parked', 'releasing', 'released')),
    notes                    text CHECK (notes IS NULL OR (length(notes) <= 4000)),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, name),
    FOREIGN KEY (workspace_id, identity_id) REFERENCES accounts.identities (workspace_id, id)
);
CREATE UNIQUE INDEX domains_legacy ON accounts.domains (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX domains_auto_renew ON accounts.domains (workspace_id, auto_renew);
CREATE INDEX domains_identity_id ON accounts.domains (workspace_id, identity_id);
CREATE INDEX domains_status ON accounts.domains (workspace_id, status);

CREATE TABLE accounts.mailboxes (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    identity_id              bigint NOT NULL,
    domain_id                bigint,
    address_ciphertext       text NOT NULL CHECK (length(address_ciphertext) <= 2000 AND length(address_ciphertext) >= 1),
    address_hash             text NOT NULL CHECK (length(address_hash) <= 128 AND length(address_hash) >= 1),
    address_hint             text NOT NULL CHECK (length(address_hint) <= 200 AND length(address_hint) >= 1),
    provider                 text NOT NULL CHECK (length(provider) <= 120 AND length(provider) >= 1),
    kind                     text NOT NULL DEFAULT 'mailbox' CHECK (kind IN ('mailbox', 'alias', 'forward')),
    forwards_to_id           bigint,
    recovery_mailbox_id      bigint,
    mfa_method               text NOT NULL DEFAULT 'unknown' CHECK (mfa_method IN ('passkey', 'security-key', 'totp', 'sms', 'none', 'unknown')),
    security_keys            integer NOT NULL DEFAULT 0 CHECK (security_keys >= 0 AND security_keys <= 20),
    recovery_phone           boolean NOT NULL DEFAULT false,
    status                   text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'unverified', 'dormant', 'to-delete', 'deleted')),
    last_reviewed_on         date,
    notes                    text CHECK (notes IS NULL OR (length(notes) <= 4000)),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, address_hash),
    FOREIGN KEY (workspace_id, identity_id) REFERENCES accounts.identities (workspace_id, id),
    FOREIGN KEY (workspace_id, domain_id) REFERENCES accounts.domains (workspace_id, id),
    FOREIGN KEY (workspace_id, forwards_to_id) REFERENCES accounts.mailboxes (workspace_id, id),
    FOREIGN KEY (workspace_id, recovery_mailbox_id) REFERENCES accounts.mailboxes (workspace_id, id)
);
CREATE UNIQUE INDEX mailboxes_legacy ON accounts.mailboxes (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX mailboxes_domain_id ON accounts.mailboxes (workspace_id, domain_id);
CREATE INDEX mailboxes_forwards_to_id ON accounts.mailboxes (workspace_id, forwards_to_id);
CREATE INDEX mailboxes_identity_id ON accounts.mailboxes (workspace_id, identity_id);
CREATE INDEX mailboxes_kind ON accounts.mailboxes (workspace_id, kind);
CREATE INDEX mailboxes_mfa_method ON accounts.mailboxes (workspace_id, mfa_method);
CREATE INDEX mailboxes_provider ON accounts.mailboxes (workspace_id, provider);
CREATE INDEX mailboxes_recovery_mailbox_id ON accounts.mailboxes (workspace_id, recovery_mailbox_id);
CREATE INDEX mailboxes_status ON accounts.mailboxes (workspace_id, status);

CREATE TABLE accounts.accounts (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    identity_id              bigint NOT NULL,
    platform                 text NOT NULL CHECK (length(platform) <= 80 AND length(platform) >= 1),
    kind                     text NOT NULL DEFAULT 'profile' CHECK (kind IN ('profile', 'page', 'channel', 'organization', 'business', 'service')),
    handle                   text CHECK (handle IS NULL OR (length(handle) <= 200)),
    public_url               text CHECK (public_url IS NULL OR (length(public_url) <= 1000)),
    login_mailbox_id         bigint,
    admin_account_id         bigint,
    social_login             text NOT NULL DEFAULT 'none' CHECK (social_login IN ('none', 'google', 'apple', 'facebook', 'other')),
    mfa_primary              text NOT NULL DEFAULT 'unknown' CHECK (mfa_primary IN ('passkey', 'security-key', 'totp', 'sms', 'none', 'unknown')),
    mfa_backup               text NOT NULL DEFAULT 'unknown' CHECK (mfa_backup IN ('passkey', 'security-key', 'totp', 'sms', 'offline-codes', 'none', 'unknown')),
    phone_bound              boolean NOT NULL DEFAULT false,
    vault_ref                text CHECK (vault_ref IS NULL OR (length(vault_ref) <= 500)),
    environment              text CHECK (environment IS NULL OR (length(environment) <= 120)),
    status                   text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned', 'setup', 'active', 'paused', 'retired')),
    last_verified_on         date,
    notes                    text CHECK (notes IS NULL OR (length(notes) <= 4000)),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, platform, handle),
    FOREIGN KEY (workspace_id, identity_id) REFERENCES accounts.identities (workspace_id, id),
    FOREIGN KEY (workspace_id, login_mailbox_id) REFERENCES accounts.mailboxes (workspace_id, id),
    FOREIGN KEY (workspace_id, admin_account_id) REFERENCES accounts.accounts (workspace_id, id)
);
CREATE UNIQUE INDEX accounts_legacy ON accounts.accounts (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX accounts_admin_account_id ON accounts.accounts (workspace_id, admin_account_id);
CREATE INDEX accounts_identity_id ON accounts.accounts (workspace_id, identity_id);
CREATE INDEX accounts_kind ON accounts.accounts (workspace_id, kind);
CREATE INDEX accounts_login_mailbox_id ON accounts.accounts (workspace_id, login_mailbox_id);
CREATE INDEX accounts_mfa_primary ON accounts.accounts (workspace_id, mfa_primary);
CREATE INDEX accounts_platform ON accounts.accounts (workspace_id, platform);
CREATE INDEX accounts_status ON accounts.accounts (workspace_id, status);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE accounts.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('identity', 'domain', 'mailbox', 'account')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE accounts.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON accounts.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['identities', 'domains', 'mailboxes', 'accounts', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE accounts.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE accounts.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON accounts.%I'
                       ' USING (workspace_id = accounts.current_workspace())'
                       ' WITH CHECK (workspace_id = accounts.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA accounts TO accounts_api;
GRANT EXECUTE ON FUNCTION accounts.current_workspace() TO accounts_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON accounts.identities, accounts.domains, accounts.mailboxes, accounts.accounts TO accounts_api;
GRANT USAGE ON SEQUENCE accounts.identities_id_seq, accounts.domains_id_seq, accounts.mailboxes_id_seq, accounts.accounts_id_seq TO accounts_api;
GRANT SELECT, INSERT ON accounts.create_keys TO accounts_api;
GRANT SELECT, INSERT ON accounts.outbox TO accounts_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON accounts.outbox TO accounts_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON accounts.outbox TO accounts_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA accounts TO accounts_publisher;
GRANT SELECT ON accounts.outbox TO accounts_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON accounts.outbox TO accounts_publisher;
